/**
 * The contract every repo builds against: how a surface is stored and served,
 * who owns it, and the one list of action names with their payloads.
 * Type-only apart from the enums, so `npm run a2ui:generate` copies it as is.
 */

/** One component of a surface: an id, a catalog component name and that component's properties. */
export interface A2uiComponent {
  id: string;
  component: string;
  [property: string]: unknown;
}

/**
 * A surface as it is stored (`comment.data.a2ui`, a tool call's `a2ui`) and as
 * every client receives it: the content of one A2UI 1.0 `createSurface`
 * message, with the data model in its latest state. A client feeds it to its
 * renderer as `{ version: '1.0', createSurface: { surfaceId, catalogId, components, dataModel } }`
 * and, when a newer copy arrives, as `updateComponents` + `updateDataModel`.
 */
export interface A2uiSurface {
  v: '1.0';
  /** `<owner kind>:<ids>`, see A2uiOwnerKind. The action router finds the surface's owner from it. */
  surfaceId: string;
  catalogId: string;
  /** The template that built it; absent on a free layout. Clients only use it as a label. */
  template?: string;
  components: A2uiComponent[];
  dataModel: Record<string, unknown>;
  /** Set once the surface was answered: it takes no further action (clients hide nothing on their own; the components already show the answered state). */
  answered?: boolean;
}

/** What a surface hangs on. The id parts after the kind are joined with ':'. */
export const A2uiOwnerKind = {
  /** `comment:<commentId>`: a chat card or a workflow step on a ticket message. */
  Comment: 'comment',
  /** `toolcall:<agentConversationId>:<messageId>:<toolCallId>`: an Operator / Copilot pane card. */
  ToolCall: 'toolcall',
  /** `task:<agentTaskId>`: a ticket pane card (question, approval, proposed reply, …). */
  Task: 'task',
  /** `ticket:<ticketId>:<slot>`: a ticket pane box that is not a task (hand-over, work on it). */
  Ticket: 'ticket',
  /** `kaicode:<sessionId>:<messageId>`: a Kai Code session card. */
  KaiCode: 'kaicode',
  /** `custom:<widgetId>`: a customer-defined widget; its actions never reach the Server. */
  Custom: 'custom',
} as const;
export type A2uiOwnerKind = (typeof A2uiOwnerKind)[keyof typeof A2uiOwnerKind];

/** Every action a surface can send. The value is the A2UI action `name` on the wire. */
